CREATE TABLE IF NOT EXISTS participants (id INT AUTO_INCREMENT PRIMARY KEY, document VARCHAR(30) NOT NULL UNIQUE, full_name VARCHAR(160) NOT NULL, phone VARCHAR(30), email VARCHAR(160), active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contributions (id INT AUTO_INCREMENT PRIMARY KEY, participant_id INT NOT NULL, year INT NOT NULL, month TINYINT NOT NULL, amount_due DECIMAL(12,2) NOT NULL, amount_paid DECIMAL(12,2) NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_contribution (participant_id,year,month), FOREIGN KEY (participant_id) REFERENCES participants(id));
CREATE TABLE IF NOT EXISTS loans (id INT AUTO_INCREMENT PRIMARY KEY, participant_id INT NOT NULL, principal DECIMAL(12,2) NOT NULL, monthly_rate DECIMAL(8,6) NOT NULL, term_months INT NOT NULL, start_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', loan_type VARCHAR(20) NOT NULL DEFAULT 'PARTICIPANT', referred_name VARCHAR(160), referred_document VARCHAR(30), FOREIGN KEY (participant_id) REFERENCES participants(id));
CREATE TABLE IF NOT EXISTS loan_installments (id INT AUTO_INCREMENT PRIMARY KEY, loan_id INT NOT NULL, installment_number INT NOT NULL, due_date DATE NOT NULL, principal_amount DECIMAL(12,2) NOT NULL, interest_amount DECIMAL(12,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0, FOREIGN KEY (loan_id) REFERENCES loans(id));
